@Component({
  template: `
    <ul>
      <li *ngFor="let user of users">{{ user.name }}</li>
      <li *ngFor="let admin of admins; trackBy: trackByAdmin">{{ admin.name }}</li>
      <li *ngFor="let guest of guests">{{ guest.name }}</li>
    </ul>
  `
})
class MultiListComponent {}

@Component({
  template: `
    <section *ngFor="let group of groups; trackBy: trackGroup">
      <span *ngFor="let item of group.items">{{ item.name }}</span>
    </section>
  `
})
class NestedListComponent {}

@Component({
  template: `
    <ng-template ngFor let-item [ngForOf]="items">
      <span>{{ item.name }}</span>
    </ng-template>
  `
})
class TemplateLoopComponent {}

@Component({
  template: `
    <div *ngFor="let order of orders; let i = index; trackBy: trackOrder">{{ i }} {{ order.id }}</div>
  `
})
class OrdersComponent {}
